-- Prediction Query
SELECT "frpm"."school name", ("frpm"."frpm count (k-12)" / "frpm"."enrollment (k-12)") AS "eligible_rate" FROM "frpm" INNER JOIN "schools" ON "frpm"."cdscode" = "schools"."cdscode" WHERE "schools"."soc" = 66 ORDER BY "frpm"."frpm count (k-12)" DESC, frpm.cdscode NULLS LAST, schools.cdscode NULLS LAST LIMIT 5;

